/* 输入仅含两数组的有效元素，没有容量占位 0。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, j = 0, m = 0, n = 0;
    n = read();
    m = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    for (i = 0; i < m; i += 1)  {
        b[i] = read();
    }
    i = 0;
    j = 0;
    /* 两个下标表示首个未输出位置，先处理耗尽边界，再选择较小头部。 */
    while ((i < n) || (j < m))  {
        if ((j == m) || ((i < n) && (a[i] <= b[j])))  {
            /* 每次输出一个输入元素并推进对应下标，重复数字仍保留。 */
            emit(a[i]);
            i = (i + 1);
        }
        else  {
            emit(b[j]);
            j = (j + 1);
        }
    }
    return 0;
}

